const { Client } = require('pg');
const bcrypt = require('bcryptjs');
const crypto = require('crypto');
const SECRET = 'yavibot-dev-secret-change-me';
const body = $json.body || {};
const cedula = String(body.cedula || '');
const password = String(body.password || '');
const client = new Client({host:'postgres',port:5432,user:'yavibot',password:'yavibot_dev_2026',database:'yavibot'});
await client.connect();
try {
  const q = await client.query(
    `SELECT u.id, u.nombres, u.password_hash, u.rol_id, r.codigo AS rol,
       COALESCE(array_agg(uc.carrera_id) FILTER (WHERE uc.carrera_id IS NOT NULL), '{}') AS carreras
     FROM usuarios_panel u JOIN roles r ON r.id = u.rol_id
     LEFT JOIN usuarios_carreras uc ON uc.usuario_id = u.id
     WHERE u.cedula = $1 AND u.activo = true GROUP BY u.id, u.rol_id, r.codigo`, [cedula]);
  const fail = { json: { _status:401, _body: { ok:false, error:{ code:'CRED', message:'Usuario o contraseña incorrectos' } } } };
  if(!q.rows.length) return [fail];
  const u = q.rows[0];
  if(!bcrypt.compareSync(password, u.password_hash)) return [fail];
  const b64 = b => Buffer.from(b).toString('base64').replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
  const header = b64(JSON.stringify({ alg:'HS256', typ:'JWT' }));
  const payload = b64(JSON.stringify({ sub:String(u.id), ced:cedula, rol:u.rol, rol_id:Number(u.rol_id), carreras:u.carreras, exp:Math.floor(Date.now()/1000)+3600 }));
  const sig = b64(crypto.createHmac('sha256', SECRET).update(header+'.'+payload).digest());
  return [{ json: { _status:200, _body: { ok:true, data:{ token: header+'.'+payload+'.'+sig, rol:u.rol, nombres:u.nombres } } } }];
} finally { await client.end(); }
